export type TaskLedgerEventType =
  | "submitted"
  | "accepted"
  | "rejected"
  | "started"
  | "completed"
  | "failed"
  | "cancelled"
  | string;

export interface TaskLedgerEvent {
  eventId: string;
  workspaceId: string;
  taskId: string;
  type: TaskLedgerEventType;
  batchIdempotencyKey: string;
  timestamp: string;
  payload?: Record<string, unknown>;
}

export type TaskLedgerStatus =
  | "pending"
  | "accepted"
  | "rejected"
  | "running"
  | "completed"
  | "failed"
  | "cancelled";

export interface WorkingContextTask {
  taskId: string;
  status: TaskLedgerStatus;
  events: TaskLedgerEvent[];
  latestEvent?: TaskLedgerEvent;
}

export interface WorkingContextView {
  workspaceId: string;
  tasks: WorkingContextTask[];
  pending: WorkingContextTask[];
  accepted: WorkingContextTask[];
  rejected: WorkingContextTask[];
  running: WorkingContextTask[];
  completed: WorkingContextTask[];
  failed: WorkingContextTask[];
  cancelled: WorkingContextTask[];
}

export interface TaskLedgerAppendInput {
  eventId: string;
  workspaceId: string;
  taskId: string;
  type: TaskLedgerEventType;
  batchIdempotencyKey: string;
  timestamp?: string;
  payload?: Record<string, unknown>;
}

export interface TaskLedgerStore {
  append(event: TaskLedgerEvent): Promise<void>;
  read(): Promise<TaskLedgerEvent[]>;
  project(): Promise<WorkingContextView>;
}

const STATUS_BY_EVENT: Record<string, TaskLedgerStatus> = {
  submitted: "pending",
  accepted: "accepted",
  rejected: "rejected",
  started: "running",
  running: "running",
  completed: "completed",
  failed: "failed",
  cancelled: "cancelled",
  canceled: "cancelled"
};

export function taskStatusForEvent(event: TaskLedgerEvent): TaskLedgerStatus {
  return STATUS_BY_EVENT[event.type] ?? "pending";
}

export function projectTaskLedger(
  workspaceId: string,
  events: readonly TaskLedgerEvent[]
): WorkingContextView {
  const ordered = events
    .filter((event) => event.workspaceId === workspaceId)
    .slice()
    .sort((left, right) => {
      const time = Date.parse(left.timestamp) - Date.parse(right.timestamp);
      if (Number.isFinite(time) && time !== 0) return time;
      return events.indexOf(left) - events.indexOf(right);
    });

  const byTask = new Map<string, TaskLedgerEvent[]>();
  for (const event of ordered) {
    const taskEvents = byTask.get(event.taskId) ?? [];
    taskEvents.push(event);
    byTask.set(event.taskId, taskEvents);
  }

  const tasks = Array.from(byTask, ([taskId, taskEvents]) => {
    const latestEvent = taskEvents[taskEvents.length - 1];
    return {
      taskId,
      status: taskStatusForEvent(latestEvent),
      events: taskEvents,
      latestEvent
    };
  });

  const withStatus = (status: TaskLedgerStatus) =>
    tasks.filter((task) => task.status === status);

  return {
    workspaceId,
    tasks,
    pending: withStatus("pending"),
    accepted: withStatus("accepted"),
    rejected: withStatus("rejected"),
    running: withStatus("running"),
    completed: withStatus("completed"),
    failed: withStatus("failed"),
    cancelled: withStatus("cancelled")
  };
}

export function isTaskLedgerEvent(value: unknown): value is TaskLedgerEvent {
  if (!value || typeof value !== "object") return false;
  const event = value as Partial<TaskLedgerEvent>;
  return (
    typeof event.eventId === "string" &&
    typeof event.workspaceId === "string" &&
    typeof event.taskId === "string" &&
    typeof event.type === "string" &&
    typeof event.batchIdempotencyKey === "string" &&
    typeof event.timestamp === "string"
  );
}

import { appendFile, mkdir, readFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import {
  isTaskLedgerEvent,
  projectTaskLedger,
  type TaskLedgerAppendInput,
  type TaskLedgerEvent,
  type TaskLedgerStore,
  type WorkingContextView
} from "../../shared/task-ledger-working-context";

export interface TaskLedgerWorkingContextOptions {
  workspaceId: string;
  workspacePath?: string;
  ledgerPath?: string;
}

export class TaskLedgerWorkingContext implements TaskLedgerStore {
  readonly workspaceId: string;
  readonly ledgerPath: string;

  constructor(options: TaskLedgerWorkingContextOptions);
  constructor(workspaceId: string, ledgerPath?: string);
  constructor(
    workspaceIdOrOptions: string | TaskLedgerWorkingContextOptions,
    ledgerPath?: string
  ) {
    if (typeof workspaceIdOrOptions === "string") {
      this.workspaceId = workspaceIdOrOptions;
      this.ledgerPath = resolve(
        ledgerPath ?? join(process.cwd(), workspaceIdOrOptions, ".task-ledger", "events.jsonl")
      );
      return;
    }

    const options = workspaceIdOrOptions;
    this.workspaceId = options.workspaceId;
    if (options.ledgerPath) {
      this.ledgerPath = resolve(options.ledgerPath);
    } else if (options.workspacePath) {
      this.ledgerPath = resolve(
        options.workspacePath,
        ".task-ledger",
        "events.jsonl"
      );
    } else {
      throw new Error("A Task Ledger path or workspace path is required");
    }
  }

  async append(input: TaskLedgerAppendInput | TaskLedgerEvent): Promise<void> {
    if (input.workspaceId !== this.workspaceId) {
      throw new Error("Task Ledger event workspace does not match this Working Context");
    }

    const event: TaskLedgerEvent = {
      ...input,
      timestamp: input.timestamp ?? new Date().toISOString()
    };

    const existing = await this.read();
    if (existing.some((item) => item.batchIdempotencyKey === event.batchIdempotencyKey)) {
      return;
    }

    await mkdir(dirname(this.ledgerPath), { recursive: true });
    await appendFile(this.ledgerPath, `${JSON.stringify(event)}\n`, "utf8");
  }

  async submit(input: TaskLedgerAppendInput): Promise<void> {
    await this.append({
      ...input,
      type: input.type || "submitted"
    });
  }

  async read(): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await readFile(this.ledgerPath, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw error;
    }

    const events: TaskLedgerEvent[] = [];
    const lines = contents.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index].trim();
      if (!line) continue;
      try {
        const parsed: unknown = JSON.parse(line);
        if (!isTaskLedgerEvent(parsed)) {
          throw new Error("invalid Task Ledger event");
        }
        if (parsed.workspaceId === this.workspaceId) events.push(parsed);
      } catch (error) {
        throw new Error(
          `Invalid Task Ledger JSONL at ${this.ledgerPath}:${index + 1}`,
          { cause: error }
        );
      }
    }
    return events;
  }

  async project(): Promise<WorkingContextView> {
    return projectTaskLedger(this.workspaceId, await this.read());
  }
}

export function createTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextOptions
): TaskLedgerWorkingContext {
  return new TaskLedgerWorkingContext(options);
}

export async function appendTaskLedgerEvent(
  context: TaskLedgerWorkingContext,
  event: TaskLedgerAppendInput | TaskLedgerEvent
): Promise<void> {
  await context.append(event);
}

export async function readTaskLedgerWorkingContext(
  context: TaskLedgerWorkingContext
): Promise<WorkingContextView> {
  return context.project();
}

