      throw new Error("Task Ledger event workspace does not match this Working Context");
    }

    const event: TaskLedgerEvent = {
      ...input,
      timestamp: input.timestamp ?? new Date().toISOString()
    };

    const existing = await this.read();
    if (existing.some((item) => item.batchIdempotencyKey === event.batchIdempotencyKey)) {
      return;
    }

    await mkdir(dirname(this.ledgerPath), { recursive: true });
    await appendFile(this.ledgerPath, `${JSON.stringify(event)}\n`, "utf8");
  }

  async submit(input: TaskLedgerAppendInput): Promise<void> {
    await this.append({
      ...input,
      type: input.type || "submitted"
    });
  }

  async read(): Promise<TaskLedgerEvent[]> {
    let contents: string;
    try {
      contents = await readFile(this.ledgerPath, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw error;
    }

    const events: TaskLedgerEvent[] = [];
    const lines = contents.split(/\r?\n/);
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index].trim();
      if (!line) continue;
      try {
        const parsed: unknown = JSON.parse(line);
        if (!isTaskLedgerEvent(parsed)) {
          throw new Error("invalid Task Ledger event");
        }
        if (parsed.workspaceId === this.workspaceId) events.push(parsed);
      } catch (error) {
        throw new Error(
          `Invalid Task Ledger JSONL at ${this.ledgerPath}:${index + 1}`,
          { cause: error }
        );
      }
    }
    return events;
  }

  async project(): Promise<WorkingContextView> {
    return projectTaskLedger(this.workspaceId, await this.read());
  }
}

export function createTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextOptions
): TaskLedgerWorkingContext {
  return new TaskLedgerWorkingContext(options);
}

export async function appendTaskLedgerEvent(
  context: TaskLedgerWorkingContext,
  event: TaskLedgerAppendInput | TaskLedgerEvent
): Promise<void> {
  await context.append(event);
}

export async function readTaskLedgerWorkingContext(
  context: TaskLedgerWorkingContext
): Promise<WorkingContextView> {
  return context.project();
}
